uth_example:
def fetch(host):
    if host.startswith("slow"):
        raise TimeoutError(f"{host} timed out")
    raise ConnectionError(f"{host} refused")

errors = []
for host in ["slow-1", "down-1", "slow-2"]:
    try:
        fetch(host)
    except OSError as exc:
        exc.add_note(f"host={host}")
        errors.append(exc)

group = ExceptionGroup("fetch failed", errors)
timeouts, rest = group.split(TimeoutError)
print(len(timeouts.exceptions), len(rest.exceptions))
print(timeouts.exceptions[0].__notes__)
print(group.subgroup(KeyError))

